    def test_brainpoolP224r1_sha3_224(
        self, name: str, pk: bytes, msg: bytes, sig: bytes, expected: bool
    ):
        decoder = SEC1Encoder()
        public_key = decoder.decode_public_key(pk, brainpoolP224r1)

        try:
            signature = DEREncoder.decode_signature(sig)
            result = verify(signature, msg, public_key, brainpoolP224r1, sha3_224)
            self.assertEqual(result, expected, name)
        except Exception:
            self.assertFalse(expected, name)
